        sum: Optional['types.EndUserSumAggregateInput'] = None,
        min: Optional['types.EndUserMinAggregateInput'] = None,
        max: Optional['types.EndUserMaxAggregateInput'] = None,
        having: Optional['types.EndUserScalarWhereWithAggregatesInput'] = None,
        count: Optional[Union[bool, 'types.EndUserCountAggregateInput']] = None,
        order: Optional[Union[Mapping['types.EndUserScalarFieldKeys', 'types.SortOrder'], List[Mapping['types.EndUserScalarFieldKeys', 'types.SortOrder']]]] = None,
